import { isOssEdition } from "./config/edition";

const params = new URLSearchParams(window.location.search);
// Preserve shared links generated by the original observatory.
const observatoryKeys = ["age", "agem", "providers", "families", "fam", "ax", "w", "decide",
  "floor", "bias", "anchor", "heat", "stage", "enc", "catalog", "me", "nr", "open", "openness", "vram", "debug", "brand"];
const showObservatory = !isOssEdition || params.get("view") === "observatory" ||
  observatoryKeys.some((key) => params.has(key));

if (showObservatory) {
  void import("./main").then(({ startObservatory }) => startObservatory());
} else {
  void import("./ui/public-decision").then(({ mountPublicDecision }) => mountPublicDecision());
}
